from save_review import save
save(1158,{2:'胜利之刃是一把光芒闪耀的精工动力阔剑，由星际战士战团冠军执掌。',4:'剑刃配重恰到好处，上面刻着历任持有者的姓名及其最辉煌的功绩。持有者还可以按下金银合金剑柄上的凹槽，以一股炽烈的能量使动力场过载，让胜利之刃劈开最厚重的装甲。'},terms=[('Blade of Triumph','胜利之刃')])
save(1159,{2:'效忠是一把光芒四射的动力剑，在第42个千年由重归世间的原体莱昂·艾尔’庄森执掌。这个名字代表了雄狮认为自己应当向父亲和整个帝国献上的忠诚。',6:'莱昂·艾尔’庄森重新苏醒后，在名为镜像卡利班的神秘领域中发现了这把剑。'},terms=[('Fealty','效忠')])
save(1160,{2:'屠戮武器是大远征期间吞世者使用的一类近战武器。它们仿自努凯里亚角斗士的仪式武器，凶狠残酷，且难以掌握，是吞世者狂暴者偏爱的武器。',7:'Excoriator Chainaxe 剥皮者链锯斧'},{7:'Excoriator 在武器语境中指剥皮者，原“严斥者”取了不合语境的词义。与战团名 Excoriators（责难者）分别登记；本武器名仍为暂定。'},[('Caedere Weapon','屠戮武器'),('Meteor Hammer','流星锤'),('Excoriator Chainaxe','剥皮者链锯斧'),('Twin Falax Blades','双法拉克斯刃'),('Barb-hook Lash','倒钩鞭')])
save(1161,{2:'电击武器是一类以电流伤敌的近战武器。',5:'电击武器装有使武器带电的供能装置。在外行人看来，它的电源组和线路可能与动力武器相似，但二者采用的技术截然不同，电击技术也远为普遍。动力武器能以毁灭性的力量撕裂装甲与血肉；电击武器则通过高压电流制服目标，除少数功率特别强大的型号外，电流本身通常并不致命。不过，帝国执法手段残酷，使用电击武器时往往还伴随着猛烈殴打，单是这样的打击就足以致人于死地。'},{2:'标题原译“震撼武器”与正文“电击武器”不一，依靠电流制敌的定义统一为后者。'},[('Shock Weapon','电击武器'),('Shock Maul','电击槌'),('Command Baton','指挥棒'),('Shock Baton','电棍'),('Shock Glove','电击手套'),('Shock Stave','电击杖'),('Electro-Goad','电击刺棒'),('Lightning Chain','闪电锁链'),('Lightning Gauntlets','闪电臂铠'),('Shock Gauntlets','电击臂铠')],title='电击武器 Shock Weapon')
